size_t strlen(const char *s) {
    const char *p = s;
    while (*p) p++;
    return p - s;
}

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void *memcpy(void *d, const void *s, size_t n) {
    char *dp = d; const char *sp = s;
    while (n--) *dp++ = *sp++;
    return d;
}

